using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Domain.Entities;using OrcaFacil.Domain.Enums;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Clients;[Authorize(Policy="SuperAdminOnly")]public sealed class BillingModel(OrcaFacilDbContext db):PageModel{public Guid ClientKey{get;private set;}public decimal Mrr{get;private set;}public int PendingInvoices{get;private set;}public decimal OpenAmount{get;private set;}public async Task<IActionResult>OnGetAsync(Guid id,CancellationToken ct){if(!await db.BusinessAccounts.AnyAsync(x=>x.Id==id&&!x.IsDeleted,ct))return NotFound();ClientKey=id;Mrr=await db.AccountModuleSubscriptions.Where(x=>x.AccountId==id&&!x.IsDeleted&&x.Status==SaasModuleSubscriptionStatus.Active).SumAsync(x=>(decimal?)(x.BillingPeriod==SaasBillingPeriod.Annual?x.ContractedPrice/12:x.ContractedPrice-x.DiscountAmount),ct)??0;PendingInvoices=await db.BillingInvoices.CountAsync(x=>x.AccountId==id&&!x.IsDeleted&&(x.Status==BillingInvoiceStatus.Pending||x.Status==BillingInvoiceStatus.Overdue),ct);OpenAmount=await db.BillingInvoices.Where(x=>x.AccountId==id&&!x.IsDeleted&&(x.Status==BillingInvoiceStatus.Pending||x.Status==BillingInvoiceStatus.Overdue)).SumAsync(x=>(decimal?)(x.Amount-x.PaidAmount),ct)??0;return Page();}}
